// VidFast Movie & TV Online Stream Provider
// Extracts streaming sources from VidFast (vidfast.vc) with dynamic token handshake and stream decryption.

var BASE_URL = "https://vidfast.vc";
var ENC_DEC_API = "https://enc-dec.app/api";
var EPISODES_API_URL = "https://data.vidsrc.sh/api.php?type=tv&tmdb=";
var UA = "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/137.0.0.0 Safari/537.36";
var DEFAULT_SERVERS = ["vRapid", "vBlaze", "Cobra", "Cine", "Bravo", "Horizon"];
var CACHE_TTL_MS = 20 * 60 * 1000;
var MAX_MOVIE_SERVERS = 2;

var HANDSHAKE_CACHE = {};

// ─── HTTP Helpers ────────────────────────────────────────────────────────────

async function fetchText(url, opts) {
  var headers = Object.assign({ "User-Agent": UA }, (opts && opts.headers) || {});
  var resp = await fetch(url, Object.assign({}, opts || {}, { headers: headers }));
  return $toString(resp.body, 0);
}

async function fetchJSON(url, opts) {
  var text = await fetchText(url, opts);
  return JSON.parse(text);
}

// ─── Provider Implementation ─────────────────────────────────────────────────

class Provider {

  getSettings() {
    return { episodeServers: DEFAULT_SERVERS };
  }

  async search(opts) {
    var media = opts.media;
    if (!media || !media.id) return [];

    var mediaType = (media.mediaType === "tv") ? "tv" : "movie";
    var embedPath = (mediaType === "tv")
      ? "/tv/" + media.id + "/1/1"
      : "/movie/" + media.id;

    return [{
      id: String(media.id),
      title: media.title || "Unknown",
      url: BASE_URL + embedPath,
      mediaType: mediaType,
    }];
  }

  async findEpisodes(id) {
    var tmdbId = String(id || "").replace(/^.*?(\d+).*$/, "$1");
    if (!tmdbId) return [];

    try {
      var meta = await fetchJSON(EPISODES_API_URL + tmdbId, {
        headers: { "Referer": BASE_URL + "/", "User-Agent": UA }
      });
      var eps = (meta && meta.data && meta.data.eps) || {};
      var seasons = Object.keys(eps).map(Number).sort(function(a, b) { return a - b; });
      var total = 0;
      var list = [];

      for (var s = 0; s < seasons.length; s++) {
        var seasonNum = seasons[s];
        var epNums = (eps[String(seasonNum)] || []).map(Number).sort(function(a, b) { return a - b; });
        for (var e = 0; e < epNums.length; e++) {
          total++;
          var epNum = epNums[e];
          list.push({
            id: tmdbId + ":" + seasonNum + ":" + epNum,
            number: total,
            title: "S" + seasonNum + " E" + epNum,
            url: BASE_URL + "/tv/" + tmdbId + "/" + seasonNum + "/" + epNum,
          });
        }
      }
      return list;
    } catch (err) {
      console.error("[VidFast] findEpisodes failed:", err);
      return [];
    }
  }

  async findMovieSources(id) {
    var tmdbId = String(id || "").replace(/^.*?(\d+).*$/, "$1");
    return this._extractSources(tmdbId, "movie", null, null, null);
  }

  async findEpisodeServer(episode, server) {
    var serverName = (server || "vRapid").trim();
    var m = (episode.title || "").match(/S(\d+)\s*E(\d+)/i);
    var season = m ? m[1] : "1";
    var epNum = m ? m[2] : String(episode.number || 1);
    var tmdbId = "";

    if (episode.id && episode.id.indexOf(":") !== -1) {
      var parts = episode.id.split(":");
      tmdbId = parts[0];
      if (parts.length >= 3) {
        season = parts[1];
        epNum = parts[2];
      }
    } else {
      tmdbId = String(episode.id || "").replace(/^.*?(\d+).*$/, "$1");
    }

    var results = await this._extractSources(tmdbId, "tv", season, epNum, serverName);
    return results && results.length > 0 ? results[0] : null;
  }

  async _getHandshake(tmdbId, contentType, season, episode) {
    var isTv = contentType === "tv";
    var cacheKey = contentType + ":" + tmdbId + ":" + (season || "") + ":" + (episode || "");
    var cached = HANDSHAKE_CACHE[cacheKey];
    if (cached && (Date.now() - cached.time < CACHE_TTL_MS)) {
      return cached.data;
    }

    var pageUrl = isTv
      ? BASE_URL + "/tv/" + tmdbId + "/" + season + "/" + episode
      : BASE_URL + "/movie/" + tmdbId;

    // Step 1: Fetch HTML and extract token
    var pageHtml = await fetchText(pageUrl, {
      headers: { "Referer": BASE_URL + "/" }
    });
    var tokenMatch = pageHtml.match(/\\"(?:en|token)\\":\\"(.*?)\\"/) || pageHtml.match(/"(?:en|token)":"([^"]+)"/);
    if (!tokenMatch) {
      throw new Error("Token payload not found in page HTML");
    }
    var enToken = tokenMatch[1];

    // Step 2: Encrypt stage 1
    var s1Data = await fetchJSON(ENC_DEC_API + "/enc-vidfast?text=" + encodeURIComponent(enToken) + "&stage=1");
    if (!s1Data || s1Data.status !== 200 || !s1Data.result) {
      throw new Error("Stage 1 encryption failed: " + (s1Data ? s1Data.error : "unknown"));
    }
    var stage1Endpoint = s1Data.result.stage1;
    var csrfToken1 = s1Data.result.token;

    // Step 3: POST stage 1 endpoint
    var s1RespText = await fetchText(stage1Endpoint, {
      method: "POST",
      headers: {
        "Referer": BASE_URL + "/",
        "X-Requested-With": "XMLHttpRequest",
        "X-CSRF-Token": csrfToken1
      }
    });

    // Step 4: Encrypt stage 2
    var s2Data = await fetchJSON(ENC_DEC_API + "/enc-vidfast?text=" + encodeURIComponent(s1RespText) + "&stage=2");
    if (!s2Data || s2Data.status !== 200 || !s2Data.result) {
      throw new Error("Stage 2 encryption failed: " + (s2Data ? s2Data.error : "unknown"));
    }
    var serversEndpoint = s2Data.result.servers;
    var streamEndpoint = s2Data.result.stream;
    var csrfToken2 = s2Data.result.token;

    // Step 5: Fetch encrypted servers
    var serversRespText = await fetchText(serversEndpoint, {
      method: "POST",
      headers: {
        "Referer": BASE_URL + "/",
        "X-Requested-With": "XMLHttpRequest",
        "X-CSRF-Token": csrfToken2
      }
    });

    // Step 6: Decrypt servers
    var decServersData = await fetchJSON(ENC_DEC_API + "/dec-vidfast", {
      method: "POST",
      body: JSON.stringify({ text: serversRespText }),
      headers: { "Content-Type": "application/json" }
    });
    if (!decServersData || decServersData.status !== 200 || !Array.isArray(decServersData.result)) {
      throw new Error("Failed to decrypt servers list");
    }

    var handshake = {
      streamEndpoint: streamEndpoint,
      csrfToken: csrfToken2,
      servers: decServersData.result
    };

    HANDSHAKE_CACHE[cacheKey] = {
      time: Date.now(),
      data: handshake
    };

    return handshake;
  }

  async _resolveServerStream(streamEndpoint, serverData, csrfToken, serverName) {
    var streamUrl = streamEndpoint + "/" + serverData.data;
    var encStreamText = await fetchText(streamUrl, {
      method: "POST",
      headers: {
        "Referer": BASE_URL + "/",
        "X-Requested-With": "XMLHttpRequest",
        "X-CSRF-Token": csrfToken
      }
    });

    var decStreamData = await fetchJSON(ENC_DEC_API + "/dec-vidfast", {
      method: "POST",
      body: JSON.stringify({ text: encStreamText }),
      headers: { "Content-Type": "application/json" }
    });

    if (!decStreamData || decStreamData.status !== 200 || !decStreamData.result || !decStreamData.result.url) {
      return null;
    }

    var streamResult = decStreamData.result;
    var subtitles = [];
    var rawTracks = streamResult.tracks || [];
    var engIdx = (typeof streamResult.englishTrackIndex === "number") ? streamResult.englishTrackIndex : 0;

    for (var k = 0; k < rawTracks.length; k++) {
      var t = rawTracks[k];
      var subUrl = t.file || t.url || "";
      if (!subUrl) continue;
      subtitles.push({
        id: t.label || ("sub-" + k),
        url: subUrl,
        language: t.label || "Unknown",
        isDefault: (k === engIdx)
      });
    }

    var isMp4 = !!streamResult.mp4;
    var videoSource = {
      url: streamResult.url,
      type: isMp4 ? "mp4" : "m3u8",
      quality: streamResult["4kAvailable"] ? "4k" : "auto",
      subtitles: subtitles
    };

    return {
      server: serverName || serverData.name || "VidFast",
      headers: {
        "Referer": BASE_URL + "/",
        "User-Agent": UA
      },
      videoSources: [videoSource]
    };
  }

  async _extractSources(tmdbId, contentType, season, episode, targetServer) {
    try {
      var handshake = await this._getHandshake(tmdbId, contentType, season, episode);
      var servers = handshake.servers;
      if (!servers || servers.length === 0) return [];

      if (targetServer) {
        var match = servers.find(function(s) {
          return (s.name || "").toLowerCase() === targetServer.toLowerCase();
        }) || servers[0];

        var srvResult = await this._resolveServerStream(
          handshake.streamEndpoint,
          match,
          handshake.csrfToken,
          match.name
        );
        return srvResult ? [srvResult] : [];
      }

      var maxServers = Math.min(MAX_MOVIE_SERVERS, servers.length);
      var results = [];
      for (var i = 0; i < maxServers; i++) {
        var s = servers[i];
        try {
          var res = await this._resolveServerStream(
            handshake.streamEndpoint,
            s,
            handshake.csrfToken,
            s.name
          );
          if (res) results.push(res);
        } catch (serverErr) {
          console.error("[VidFast] Error resolving server " + s.name + ":", serverErr);
        }
      }
      return results;
    } catch (e) {
      console.error("[VidFast] Extraction error:", e);
      return [];
    }
  }
}
